<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from '@/shared/components/WareState.vue';import{sessionStore}from '@/store/session';import{transportApi}from '../../api/transport.api';import type{DispatchPage,DispatchTask}from '../../models/vehicle';
const today=()=>new Date().toISOString().slice(0,10);const roundNo=ref(today()),keyword=ref(''),status=ref(0),page=ref(1),loading=ref(true),error=ref(''),detail=ref<DispatchTask|null>(null),data=ref<DispatchPage>({current:1,size:20,total:0,summary:{dispatched:0,running:0,completed:0},records:[]});const canManage=computed(()=>sessionStore.can('transport.dispatch.manage'));
async function load(reset=true){loading.value=true;error.value='';try{if(reset)page.value=1;data.value=await transportApi.dispatches({page:page.value,size:20,roundNo:roundNo.value,keyword:keyword.value.trim(),status:status.value})}catch(e){error.value=e instanceof Error?e.message:'派车任务加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function pickDate(e:any){roundNo.value=e.detail.value;load()}function choose(s:number){status.value=s;load()}async function change(t:DispatchTask,s:number){const names:Record<number,string>={2:'开始执行',3:'完成任务',4:'撤销任务',5:'异常终止'};uni.showModal({title:names[s],content:`确认将 ${t.plateNo} 的任务设为“${names[s]}”吗？`,success:async r=>{if(!r.confirm)return;detail.value=await transportApi.dispatchStatus(t.id,s);load()}})}
onLoad(()=>load());onPullDownRefresh(()=>load());
</script>
<template><view class="page"><view class="summary"><view><b>{{data.total}}</b><text>任务合计</text></view><view><b>{{data.summary.dispatched}}</b><text>已派车</text></view><view><b>{{data.summary.running}}</b><text>执行中</text></view><view><b>{{data.summary.completed}}</b><text>已完成</text></view></view><view class="tools"><picker mode="date" :value="roundNo" @change="pickDate"><view class="date">场次：{{roundNo}}⌄</view></picker><view class="search"><input v-model="keyword" placeholder="任务号 / 车牌 / 司机 / 基地" confirm-type="search" @confirm="load()"/><text @click="load()">查询</text></view></view><scroll-view scroll-x class="tabs"><view class="tab-row"><view v-for="x in [{s:0,n:'全部'},{s:1,n:'已派车'},{s:2,n:'执行中'},{s:3,n:'已完成'},{s:4,n:'已撤销'}]" :key="x.s" :class="{active:status===x.s}" @click="choose(x.s)">{{x.n}}</view></view></scroll-view><WareState v-if="loading" type="loading" title="正在加载派车任务"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load()"/><view v-else-if="data.records.length" class="list"><view v-for="t in data.records" :key="t.id" class="card" @click="detail=t"><view class="head"><view><b>{{t.plateNo}}</b><small>{{t.vehicleName}} · {{t.driverName||'未配置司机'}}</small></view><span :class="`s${t.status}`">{{t.statusStr}}</span></view><view class="base">{{t.responsibleBaseName||'未配置责任基地'}}</view><view class="route">{{t.route}}</view><view class="foot"><text>{{t.dispatchNo}}</text><text>查看详情 ›</text></view></view></view><WareState v-else type="empty" title="暂无派车任务" description="当前场次和筛选条件下没有任务"/><view v-if="detail" class="mask" @click="detail=null"><view class="drawer" @click.stop><view class="handle"/><view class="drawer-head"><view><b>{{detail.plateNo}}</b><small>{{detail.dispatchNo}}</small></view><text @click="detail=null">关闭</text></view><view class="grid"><view><small>任务状态</small><b>{{detail.statusStr}}</b></view><view><small>场次</small><b>{{detail.roundNo}}</b></view><view><small>司机</small><b>{{detail.driverName||'未配置'}}</b></view><view><small>车型</small><b>{{detail.vehicleName||'未配置'}}</b></view><view><small>责任基地</small><b>{{detail.responsibleBaseName||'未配置'}}</b></view><view><small>任务类型</small><b>{{detail.typeStr}}</b></view></view><view class="route-detail"><small>运输路线</small><text>{{detail.route}}</text></view><view v-if="canManage&&[1,2].includes(detail.status)" class="actions"><button v-if="detail.status===1" class="primary" @click="change(detail,2)">开始执行</button><button v-if="detail.status===2" class="primary" @click="change(detail,3)">完成任务</button><button @click="change(detail,4)">撤销</button><button class="danger" @click="change(detail,5)">异常终止</button></view></view></view></view></template>
<style scoped>.page{box-sizing:border-box;min-height:100vh;padding:18rpx 20rpx;background:var(--wms-surface-page)}.summary{display:grid;grid-template-columns:repeat(4,1fr);overflow:hidden;border-radius:14rpx;background:#fff}.summary view{padding:17rpx 4rpx;border-right:1rpx solid var(--wms-border);text-align:center}.summary view:last-child{border:0}.summary b,.summary text{display:block}.summary b{font-size:31rpx}.summary text{margin-top:3rpx;color:var(--wms-text-secondary);font-size:17rpx}.tools{display:grid;grid-template-columns:210rpx 1fr;gap:10rpx;margin-top:14rpx}.date,.search{box-sizing:border-box;height:66rpx;border:1rpx solid var(--wms-border);border-radius:10rpx;background:#fff;font-size:20rpx}.date{padding:0 13rpx;line-height:66rpx}.search{display:flex;align-items:center;padding:0 13rpx}.search input{min-width:0;flex:1;font-size:20rpx}.search text{color:var(--wms-primary-700)}.tabs{margin:12rpx 0}.tab-row{display:inline-flex;gap:9rpx}.tab-row view{padding:10rpx 17rpx;border:1rpx solid var(--wms-border);border-radius:9rpx;background:#fff;color:var(--wms-text-secondary);font-size:19rpx;white-space:nowrap}.tab-row .active{border-color:var(--wms-primary-700);background:var(--wms-surface-soft);color:var(--wms-primary-700);font-weight:700}.list{display:flex;flex-direction:column;gap:11rpx}.card{padding:18rpx;border:1rpx solid var(--wms-border);border-radius:14rpx;background:#fff}.head,.drawer-head,.actions{display:flex;align-items:center;justify-content:space-between}.head b,.head small{display:block}.head b{font-size:26rpx}.head small{margin-top:4rpx;color:var(--wms-text-secondary);font-size:19rpx}.head span{padding:5rpx 10rpx;border-radius:7rpx;background:#e8f6f3;color:var(--wms-primary-700);font-size:18rpx}.head .s3{background:#edf7ea;color:#397c30}.head .s4,.head .s5,.head .s6{background:#f1f2f2;color:#667}.base{margin-top:15rpx;font-size:22rpx;font-weight:700}.route{margin-top:6rpx;color:var(--wms-text-secondary);font-size:19rpx}.foot{display:flex;justify-content:space-between;margin-top:14rpx;padding-top:12rpx;border-top:1rpx solid var(--wms-border);color:var(--wms-text-secondary);font-size:17rpx}.foot text:last-child{color:var(--wms-primary-700)}.mask{position:fixed;z-index:80;inset:0;display:flex;align-items:flex-end;background:#0007}.drawer{box-sizing:border-box;width:100%;padding:14rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:26rpx 26rpx 0 0;background:#fff}.handle{width:66rpx;height:7rpx;margin:0 auto 18rpx;border-radius:7rpx;background:var(--wms-border)}.drawer-head b,.drawer-head small{display:block}.drawer-head b{font-size:29rpx}.drawer-head small{margin-top:4rpx;color:var(--wms-text-secondary)}.drawer-head>text{color:var(--wms-primary-700)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10rpx;margin-top:20rpx}.grid view,.route-detail{padding:15rpx;border-radius:10rpx;background:var(--wms-surface-page)}.grid small,.grid b,.route-detail small,.route-detail text{display:block}.grid small,.route-detail small{color:var(--wms-text-secondary);font-size:18rpx}.grid b,.route-detail text{margin-top:5rpx;font-size:21rpx}.route-detail{margin-top:10rpx}.actions{gap:9rpx;margin-top:18rpx}.actions button{flex:1;margin:0;font-size:19rpx}.actions .primary{background:var(--wms-primary-700);color:#fff}.actions .danger{color:var(--wms-danger)}</style>
